function openOnboarding(){onboardStep=1;onboardDraft={name:state.profile.name,role:state.profile.role,force:state.profile.force,city:state.homeCity,mode:state.mode,arrival:state.arrival,leave:state.leaveDate,dest:state.dest,interests:[...(state.profile.interests||[])],verified:state.profile.verified};renderOnboarding();}
function renderOnboarding(){
 let c,a;if(onboardStep===1){c=`<div class="onboard-hero"><img src="${image('chegada')}" alt="Cidade de Manaus"></div><h2 class="onboard-h">A rede que acompanha a vida militar.</h2><p>Encontre serviços, oportunidades e experiências da comunidade, cidade por cidade.</p><p class="form-note">Cadastro de demonstração. Nenhuma consulta de identidade é feita nesta versão.</p>`;a=btn('Começar','onboard-next','','filled');}
 if(onboardStep===2){c=`${field('onboard-name','Seu nome',onboardDraft.name,'required minlength="3" maxlength="80"')}${selectField('onboard-role','Seu vínculo',[['ativa','Militar da ativa'],['veterano','Veterano'],['pensionista','Pensionista militar'],['familia','Família de militar']],onboardDraft.role)}${selectField('onboard-force','Força',['Aeronáutica','Exército','Marinha'],onboardDraft.force)}${onboardDraft.role==='familia'?field('onboard-code','Código de convite','','required supporting-text="Use um código criado em Você → Família convidada."'):''}<label class="choice"><md-checkbox id="onboard-terms" aria-label="Aceitar os termos do protótipo"></md-checkbox><span class="txt"><b>Usar o modo teste</b><small>Os dados de demonstração ficam no meu dispositivo.</small></span></label>`;a=btn('Voltar','onboard-prev','','text')+btn('Conferir perfil de teste','onboard-next','','filled');}
 if(onboardStep===3){c=`<div class="choice">${icon('verified_user')}<span class="txt"><b>Escolha o resultado da verificação</b><small>Isso permite testar as permissões de leitura e publicação.</small></span></div>${[['yes','Verificado','Pode participar e publicar na própria cidade.'],['pending','Em análise','Pode consultar conteúdo, mas não publicar.']].map(([v,t,d])=>`<label class="choice"><md-radio name="verify" value="${v}" ${onboardDraft.verified===(v==='yes')?'checked':''} aria-label="${t}"></md-radio><span class="txt"><b>${t}</b><small>${d}</small></span></label>`).join('')}`;a=btn('Voltar','onboard-prev','','text')+btn('Continuar','onboard-next','','filled');}
 if(onboardStep===4){c=`${selectField('onboard-city','Sua cidade',CITY_NAMES,onboardDraft.city)}${selectField('onboard-mode','Seu momento',[['moro','Moro na cidade'],['chegando','Estou chegando'],['saindo','Estou saindo']],onboardDraft.mode)}<label class="field-label" id="onboard-date-wrap"><span id="onboard-date-label"></span><input id="onboard-date" type="date" min="${dateISO()}"></label><div id="onboard-dest-wrap">${selectField('onboard-dest','Destino da transferência',CITY_NAMES,onboardDraft.dest)}</div><p class="form-note">A home organiza seu plano e as ofertas para esse momento. Você pode mudar depois.</p>`;a=btn('Voltar','onboard-prev','','text')+btn('Continuar','onboard-next','','filled');}
 if(onboardStep===5){const d=onboardDraft,turma=d.mode==='chegando'?turmaName(d.city,cycleOf(d.arrival)):d.mode==='saindo'&&d.dest&&d.dest!==d.city?turmaName(d.dest,cycleOf(d.leave)):'';c=`<h2>Do que você quer participar?</h2><p class="form-note">Marque até 3. Usamos isso só para sugerir grupos em ${esc(d.city)}.</p>${interestsHtml(d.interests||[])}${turma?`<div class="choice onboard-turma">${icon('flight_land')}<span class="txt"><b>Você entra em ${esc(turma)}</b><small>Grupo automático de quem chega à cidade no mesmo ciclo, de novembro a outubro. Você pode sair quando quiser.</small></span></div>`:''}`;a=btn('Voltar','onboard-prev','','text')+btn('Entrar no Bivaque','onboard-finish','','filled');}
 showDialog('Seu cadastro',`<div class="onboard-step"><span>Etapa ${onboardStep} de 5</span>${pill('Modo teste')}</div><md-linear-progress value="${onboardStep/5}" aria-label="Etapa ${onboardStep} de 5"></md-linear-progress>${c}`,a,'onboarding');
 for(const [id,key] of [['onboard-city','city'],['onboard-mode','mode'],['onboard-dest','dest']])$('#'+id)?.addEventListener('change',e=>onboardDraft[key]=e.target.value);
 $('#onboard-date')?.addEventListener('change',e=>{onboardDraft[onboardDraft.mode==='saindo'?'leave':'arrival']=e.target.value;});
  $('#onboard-mode')?.addEventListener('change',()=>onboardMomentFields());
 onboardMomentFields();
  $('#onboard-role')?.addEventListener('change',()=>{onboardDraft.name=$('#onboard-name').value;onboardDraft.role=$('#onboard-role').value;onboardDraft.force=$('#onboard-force').value;renderOnboarding();});
}
function onboardGroups(){return state.groups.filter(g=>g.city===onboardDraft.city&&(!g.modes||g.modes.includes(onboardDraft.mode)));}
// Etapa 4: mostra só os campos do momento, sem redesenhar (o seletor em uso não é destruído
// e o foco permanece). Chegada e saída têm datas próprias no rascunho.
function onboardMomentFields(){const mode=onboardDraft.mode,wrap=$('#onboard-date-wrap'),dest=$('#onboard-dest-wrap'),date=$('#onboard-date');if(!wrap||!date)return;wrap.style.display=mode==='moro'?'none':'';dest.style.display=mode==='saindo'?'':'none';$('#onboard-date-label').textContent=mode==='saindo'?'Data da saída':'Data de chegada';date.value=(mode==='saindo'?onboardDraft.leave:onboardDraft.arrival)||'';}
